public function getPrevProduct($product_id,$category_id) {
	$sql = "SELECT p.product_id FROM " . DB_PREFIX . "product p ";
	$sql .= " INNER JOIN " . DB_PREFIX . "product_to_store p2s on ( p.product_id = p2s.product_id and p2s.store_id = " . (int)$this->config->get('config_store_id') . ") ";
	if($category_id) {
		$sql .= " INNER JOIN  " . DB_PREFIX . "product_to_category p2c on (p.product_id = p2c.product_id and p2c.category_id = " . (int)$category_id . ") ";
	}

	$sql .= " WHERE p.product_id < " . (int)$product_id . " AND status=1 ORDER BY p.product_id DESC LIMIT 0,1";
	$query = $this->db->query($sql);
	if(!$query->num_rows)
		return false;

	return $query->row['product_id'];
}

public function getNextProduct($product_id,$category_id) {
	$sql = "SELECT p.product_id FROM " . DB_PREFIX . "product p ";
	$sql .= " INNER JOIN " . DB_PREFIX . "product_to_store p2s on ( p.product_id = p2s.product_id and p2s.store_id = " . (int)$this->config->get('config_store_id') . ") ";
	if($category_id) {
		$sql .= " INNER JOIN  " . DB_PREFIX . "product_to_category p2c on (p.product_id = p2c.product_id and p2c.category_id = " . (int)$category_id . ") ";
	}
	$sql .= " WHERE p.product_id > " . (int)$product_id . " AND status=1 ORDER BY p.product_id ASC LIMIT 0,1";
	$query = $this->db->query($sql);
	if(!$query->num_rows)
		return false;

	return $query->row['product_id'];
	}
